@@ -67,6 +67,16 @@ dependencies {
     if (dartDefines.cronetHttpNoPlay == 'true') {
         implementation 'org.chromium.net:cronet-embedded:143.7445.0'
     } else {
+        // TODO: When upgrading, check whether the pin to
+        // org.chromium.net:cronet-api:143.7445.0 is still necessary.
         implementation "com.google.android.gms:play-services-cronet:18.1.1"
+        // `play-services-cronet:18.1.1` depends on `cronet-api:141.7340.3`.
+        // That version of `cronet-api`, and its `cronet-shared` dependency,
+        // both use the "org.chromium.net" namespace, which breaks builds that
+        // set `android.uniquePackageNames=true` (the default starting with
+        // Android Gradle Plugin 9).
+        //
+        // See https://github.com/dart-lang/http/issues/1932
+        implementation 'org.chromium.net:cronet-api:143.7445.0'
     }
 }

